cd "/home/ark/Stuff/school/2026-2027/courses/fall/art of web programming/mp1/src/css" && cat > _mixins.scss <<'EOF'
@use 'sass:map';
@use 'variables' as v;

// Media query down to a named breakpoint, e.g. @include respond-to('sm') { ... }
@mixin respond-to($name) {
    $width: map.get(v.$breakpoints, $name);

    @if $width == null {
        @error 'Unknown breakpoint: #{$name}';
    }

    @media (max-width: $width) {
        @content;
    }
}

@mixin flex-center($direction: row) {
    display: flex;
    flex-direction: $direction;
    align-items: center;
    justify-content: center;
}

// Full-bleed image that stays put while the page scrolls past it.
@mixin fixed-bg($image, $position: center) {
    background-image: $image;
    background-position: $position;
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
}

// Tints a fixed background so foreground text keeps its contrast.
@mixin overlay($color, $opacity) {
    position: relative;

    &::before {
        content: '';
        position: absolute;
        inset: 0;
        background-color: rgba($color, $opacity);
    }

    > * {
        position: relative;
    }
}
EOF
cat > _base.scss <<'EOF'
@use 'variables' as v;
@use 'mixins' as m;

*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
    background-color: v.$cream;
    color: v.$ink;
    font-family: v.$font-body;
    font-size: v.$text-base;
    font-weight: v.$weight-regular;
    line-height: 1.65;
}

h1,
h2,
h3 {
    margin: 0;
    font-weight: v.$weight-bold;
    line-height: 1.15;
}

p {
    margin: 0;
}

ul {
    margin: 0;
    padding: 0;
    list-style: none;
}

a {
    color: inherit;
    text-decoration: none;
}

button {
    font: inherit;
    color: inherit;
    border: none;
    background: none;
    cursor: pointer;
}

img,
video {
    display: block;
    max-width: 100%;
}

// Full-width horizontal band. Sections set their own background; the padding is shared.
.stripe {
    width: 100%;
    padding: v.$space-xl v.$space-md;
    overflow: hidden;

    @include m.respond-to('sm') {
        padding: v.$space-lg v.$space-sm;
    }
}

// Centres a section's content and caps its measure on wide screens.
.container {
    width: 100%;
    max-width: v.$container-width;
    margin: 0 auto;
    text-align: center;
}

.section__title {
    font-size: v.$text-2xl;
    color: v.$navy;

    @include m.respond-to('sm') {
        font-size: v.$text-xl;
    }
}

.section__lead {
    max-width: 38rem;
    margin: v.$space-sm auto 0;
    color: v.$ink-muted;
    font-size: v.$text-lg;
}

// Icons inherit their colour and scale with the font size of their container.
.icon {
    width: 1em;
    height: 1em;
    fill: currentColor;
}
EOF
cat > main.scss <<'EOF'
// Partials are loaded in cascade order: base first, then layout, then components.
@use 'base';
EOF
echo ok && ls

