margin: 0 auto;\n    text-align: center;\n}\n\n.section__title {\n    font-size: v.$text-2xl;\n    color: v.$navy;\n\n    @include m.respond-to('sm') {\n        font-size: v.$text-xl;\n    }\n}\n\n.section__lead {\n    max-width: 38rem;\n    margin: v.$space-sm auto 0;\n    color: v.$ink-muted;\n    font-size: v.$text-lg;\n}\n\n// Icons inherit their colour and scale with the font size of their container.\n.icon {\n    width: 1em;\n    height: 1em;\n    fill: currentColor;\n}\n","*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  background-color: #f7f4ec;\n  color: #1c2434;\n  font-family: \"Nunito\", \"Segoe UI\", system-ui, sans-serif;\n  font-size: 1rem;\n  font-weight: 400;\n  line-height: 1.65;\n}\n\nh1,\nh2,\nh3 {\n  margin: 0;\n  font-weight: 800;\n  line-height: 1.15;\n}\n\np {\n  margin: 0;\n}\n\nul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\nbutton {\n  font: inherit;\n  color: inherit;\n  border: none;\n  background: none;\n  cursor: pointer;\n}\n\nimg,\nvideo {\n  display: block;\n  max-width: 100%;\n}\n\n.stripe {\n  width: 100%;\n  padding: 5rem 1.75rem;\n  overflow: hidden;\n}\n@media (max-width: 768px) {\n  .stripe {\n    padding: 3rem 1rem;\n  }\n}\n\n.container {\n  width: 100%;\n  max-width: 72rem;\n  margin: 0 auto;\n  text-align: center;\n}\n\n.section__title {\n  font-size: 2.25rem;\n  color: #16305c;\n}\n@media (max-width: 768px) {\n  .section__title {\n    font-size: 1.5rem;\n  }\n}\n\n.section__lead {\n  max-width: 38rem;\n  margin: 1rem auto 0;\n  color: #5a6579;\n  font-size: 1.125rem;\n}\n\n.icon {\n  width: 1em;\n  height: 1em;\n  fill: currentColor;\n}","// Design tokens. Every colour, size and timing used on the page resolves to one of these.\n\n// Palette sampled from assets/background.png.\n$navy:        #16305c;\n$navy-deep:   #0d1f3d;\n$sky:         #8ecae6;\n$sky-pale:    #dceff9;\n$cream:       #f7f4ec;\n$white:       #ffffff;\n$orange:      #f28c28;\n$teal:        #2a9d8f;\n$ink:         #1c2434;\n$ink-muted:   #5a6579;\n\n// Typography\n$font-body: 'Nunito', 'Segoe UI', system-ui, sans-serif;\n$weight-regular: 400;\n$weight-semibold: 600;\n$weight-bold: 800;\n\n$text-sm:   0.875rem;\n$text-base: 1rem;\n$text-lg:   1.125rem;\n$text-xl:   1.5rem;\n$text-2xl:  2.25rem;\n$text-3xl:  4rem;\n\n// Spacing scale\n$space-xs: 0.5rem;\n$space-sm: 1rem;\n$space-md: 1.75rem;\n$space-lg: 3rem;\n$space-xl: 5rem;\n\n// Layout\n$container-width: 72rem;\n$radius: 0.75rem;\n$shadow-soft: 0 0.5rem 1.5rem rgba($navy-deep, 0.12);\n$shadow-lifted: 0 1rem 2.5rem rgba($navy-deep, 0.22);\n\n// Navbar: the shrunk height is what section scroll offsets are measured against.\n$nav-height: 5.5rem;\n$nav-height-shrunk: 3.75rem;\n\n// Motion\n$ease: cubic-bezier(0.4, 0, 0.2, 1);\n$duration: 0.3s;\n\n// Breakpoints, keyed for the respond-to() mixin.\n$breakpoints: (\n    'lg': 1200px,\n    'md': 992px,\n    'sm': 768px,\n    'xs': 576px\n);\n","@use 'sass:map';\n@use 'variables' as v;\n\n// Media query down to a named breakpoint, e.g. @include respond-to('sm') { ... }\n@mixin respond-to($name) {\n    $width: map.get(v.$breakpoints, $name);\n\n    @if $width == null {\n        @error 'Unknown breakpoint: #{$name}';\n    }\n\n    @media (max-width: $width) {\n        @content;\n    }\n}\n\n@mixin flex-center($direction: row) {\n    display: flex;\n    flex-direction: $direction;\n    align-items: center;\n    justify-content: center;\n}\n\n// Full-bleed image that stays put while the page scrolls past it.\n@mixin fixed-bg($image, $position: center) {\n    background-image: $image;\n    background-position: $position;\n    background-size: cover;\n    background-repeat: no-repeat;\n    background-attachment: fixed;\n}\n\n// Tints a fixed background so foreground text keeps its contrast.\n@mixin overlay($color, $opacity) {\n    position: relative;\n\n    &::before {\n        content: '';\n        position: absolute;\n        inset: 0;\n        background-color: rgba($color, $opacity);\n    }\n\n    > * {\n        position: relative;\n    }\n}\n"],"sourceRoot":""}]);
