ol id=\"icon-twitter\" viewBox=\"0 0 512 512\">\n                <path d=\"M389.2 48h70.6L305.6 224.2 487 464H345L233.7 318.6 106.5 464H35.8L200.7 275.5 26.8 48H172.4L272.9 180.9 389.2 48zM364.4 421.8h39.1L151.1 88h-42L364.4 421.8z\"/>\n            </symbol>\n            <symbol id=\"icon-instagram\" viewBox=\"0 0 448 512\">\n                <path d=\"M224.1 141c-63.6 0-114.9 51.3-114.9 114.9s51.3 114.9 114.9 114.9S339 319.5 339 255.9 287.7 141 224.1 141zm0 189.6c-41.1 0-74.7-33.5-74.7-74.7s33.5-74.7 74.7-74.7 74.7 33.5 74.7 74.7-33.6 74.7-74.7 74.7zm146.4-194.3c0 14.9-12 26.8-26.8 26.8-14.9 0-26.8-12-26.8-26.8s12-26.8 26.8-26.8 26.8 12 26.8 26.8zm76.1 27.2c-1.7-35.9-9.9-67.7-36.2-93.9-26.2-26.2-58-34.4-93.9-36.2-37-2.1-147.9-2.1-184.9 0-35.8 1.7-67.6 9.9-93.9 36.1s-34.4 58-36.2 93.9c-2.1 37-2.1 147.9 0 184.9 1.7 35.9 9.9 67.7 36.2 93.9s58 34.4 93.9 36.2c37 2.1 147.9 2.1 184.9 0 35.9-1.7 67.7-9.9 93.9-36.2 26.2-26.2 34.4-58 36.2-93.9 2.1-37 2.1-147.8 0-184.8zM398.8 388c-7.8 19.6-22.9 34.7-42.6 42.6-29.5 11.7-99.5 9-132.1 9s-102.7 2.6-132.1-9c-19.6-7.8-34.7-22.9-42.6-42.6-11.7-29.5-9-99.5-9-132.1s-2.6-102.7 9-132.1c7.8-19.6 22.9-34.7 42.6-42.6 29.5-11.7 99.5-9 132.1-9s102.7-2.6 132.1 9c19.6 7.8 34.7 22.9 42.6 42.6 11.7 29.5 9 99.5 9 132.1s2.7 102.7-9 132.1z\"/>\n            </symbol>\n            <symbol id=\"icon-youtube\" viewBox=\"0 0 576 512\">\n                <path d=\"M549.655 124.083c-6.281-23.65-24.787-42.276-48.284-48.597C458.781 64 288 64 288 64S117.22 64 74.629 75.486c-23.497 6.322-42.003 24.947-48.284 48.597-11.412 42.867-11.412 132.305-11.412 132.305s0 89.438 11.412 132.305c6.281 23.65 24.787 41.5 48.284 47.821C117.22 448 288 448 288 448s170.78 0 213.371-11.486c23.497-6.321 42.003-24.171 48.284-47.821 11.412-42.867 11.412-132.305 11.412-132.305s0-89.438-11.412-132.305zm-317.51 213.508V175.185l142.739 81.205-142.739 81.201z\"/>\n            </symbol>\n        </svg>\n\n        <nav id=\"navbar\" class=\"navbar\">\n            <div class=\"navbar__inner\">\n                <a class=\"navbar__brand\" href=\"#home\">Bob's 10-in-1</a>\n                <ul class=\"navbar__menu\">\n                    <li><a class=\"navbar__link\" href=\"#home\">Home</a></li>\n                    <li><a class=\"navbar__link\" href=\"#functionality\">Functionality</a></li>\n                    <li><a class=\"navbar__link\" href=\"#about\">About</a></li>\n                    <li><a class=\"navbar__link\" href=\"#guarantee\">Guarantee</a></li>\n                    <li><a class=\"navbar__link\" href=\"#reviews\">Reviews</a></li>\n                    <li><a class=\"navbar__link\" href=\"#support\">Support</a></li>\n                    <li><a class=\"navbar__link\" href=\"#contact\">Contact</a></li>\n                </ul>\n            </div>\n        </nav>\n\n        <header id=\"home\" class=\"stripe hero\">\n            <div class=\"hero__content\">\n                <h1 class=\"hero__title\">Bob's 10-in-1</h1>\n                <p class=\"hero__tagline\">Your one-stop shop for all things personal hygiene</p>\n            </div>\n        </header>\n\n        <main>\n            <section id=\"functionality\" class=\"stripe functionality\">\n                <div class=\"container\">\n                    <h2 class=\"section__title\">Ten jobs, one bottle</h2>\n                    <p class=\"section__lead\">Tap any job to read what the bottle does about it.</p>\n\n                    <ul class=\"tiles\">\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Shampoo</span>\n                                <span class=\"tile__teaser\">Clean hair</span>\n                                <span class=\"tile__detail\" hidden>A dense, sudsy lather that lifts a week of city grime out of the roots without stripping the natural oils your scalp spent all that effort making. Works in hard water, soft water, and the water in Kansas.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Conditioner</span>\n                                <span class=\"tile__teaser\">Soft hair</span>\n                                <span class=\"tile__detail\" hidden>The same pour that washed your hair thirty seconds ago now conditions it, because the formula is smart enough to know what it already did. Leaves strands smooth, weightless, and noticeably easier to argue with.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Moisturizer</span>\n                                <span class=\"tile__teaser\">Soft skin</span>\n                                <span class=\"tile__detail\" hidden>Sinks in within seconds and holds moisture for a full sixteen hours, so elbows, knuckles, and shins stop looking like a topographic map. Non-greasy, unscented, and safe to apply immediately before shaking someone's hand.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Sunscreen</span>\n                                <span class=\"tile__teaser\">Blocked rays</span>\n                                <span class=\"tile__detail\" hidden>Broad-spectrum SPF 50 that goes on clear instead of leaving you chalk-white at the beach. Water resistant for eighty minutes, which is roughly seventy-five minutes longer than anyone actually stays in the ocean.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Toothpaste</span>\n                                <span class=\"tile__teaser\">Clean teeth</span>\n                                <span class=\"tile__detail\" hidden>Fluoride, a gentle polishing agent, and a mint note that reads as \"fresh\" rather than \"industrial.\" Dentist approved, assuming your dentist has not read the rest of this list.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Mouthwash</span>\n                                <span class=\"tile__teaser\">Fresh breath</span>\n                                <span class=\"tile__detail\" hidden>Swish for thirty seconds and the formula handles everything brushing missed, including the garlic decision you made at lunch. Alcohol-free, so it cleans your mouth without setting fire to it.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Shaving cream</span>\n                                <span class=\"tile__teaser\">Smooth shave</span>\n                                <span class=\"tile__detail\" hidden>Whips into a cushioned lather that lets the blade glide instead of drag, which is the entire difference between a shave and a regret. Rinses clean off the razor in one pass under the tap.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Skin toner</span>\n                                <span class=\"tile__teaser\">Even tone</span>\n                                <span class=\"tile__detail\" hidden>Balances your skin back to its preferred pH after everything else in this bottle has had a turn. Tightens the look of pores and takes the shine off a forehead that has been through a lot today.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Foot cream</span>\n                                <span class=\"tile__teaser\">Happy feet</span>\n                                <span class=\"tile__detail\" hidden>A thicker application for heels that have quietly become a structural concern. Softens hard skin overnight and neutralizes odor at the source, so your shoes stop being a topic of conversation.</span>\n                            </button>\n                        </li>\n                        <li>\n                            <button class=\"tile\" type=\"button\">\n                                <span class=\"tile__name\">Mayonnaise</span>\n                                <span class=\"tile__teaser\">On sandwiches</span>\n                                <span class=\"tile__detail\" hidden>Creamy, tangy, and spreadable straight from the pump. We are aware of how this looks next to the other nine. Our legal team asks that you keep a separate bottle for the kitchen, and our marketing team asks that you do not.</span>\n                            </button>\n                        </li>\n                    </ul>\n                </div>\n            </section>\n\n            <section id=\"about\" class=\"stripe about\">\n                <div class=\"container\">\n                    <h2 class=\"section__title\">About us</h2>\n\n                    <div class=\"columns\">\n                        <article class=\"column\">\n                            <svg class=\"icon column__icon\" aria-hidden=\"true\"><use href=\"#icon-user\"/></svg>\n                            <h3 class=\"column__title\">Who are we</h3>\n                            <p>Bob's 10-in-1 is a family-run business for 15 generations. We noticed how people were buying 10 products for 10 things and decided to make it one product that does everything.</p>\n                        </article>\n                        <article class=\"column\">\n                            <svg class=\"icon column__icon\" aria-hidden=\"true\"><use href=\"#icon-map\"/></svg>\n                            <h3 class=\"column__title\">Where are we</h3>\n                            <p>Bob's 10-in-1 is in every store in America, except in Kansas and at some Chipotle locations.</p>\n                        </article>\n                        <article class=\"column\">\n                            <svg class=\"icon column__icon\" aria-hidden=\"true\"><use href=\"#icon-question\"/></svg>\n                            <h3 class=\"column__title\">The future</h3>\n                            <p>Bob's son, Bob is proud to carry on the family legacy. Our new products include an 11-in-one which will soon be usable as engine oil.</p>\n                        </article>\n                    </div>\n                </div>\n            </section>\n\n            <section id=\"guarantee\" class=\"stripe guarantee\">\n                <p class=\"guarantee__text\">\n                    Satisfaction or your money back\n                    <span class=\"guarantee__fine\">(100% return fee applies)</span>\n                </p>\n            </section>\n\n            <section id=\"reviews\" class=\"stripe reviews\">\n                <div class=\"container\">\n                    <h2 class=\"section__title\">What people are saying</h2>\n\n                    <div class=\"carousel\">\n                        <button class=\"carousel__arrow carousel__arrow--prev\" type=\"button\" aria-label=\"Previous review\">\n                            <svg class=\"icon\" aria-hidden=\"true\"><use href=\"#icon-chevron-left\"/></svg>\n        