        title.textContent = tile.querySelector('.tile__name').textContent;
        body.textContent = tile.querySelector('.tile__detail').textContent;
        modal.hidden = false;
        opener = tile;
        closeButton.focus();
    }

    function close() {
        modal.hidden = true;

        if (opener) {
            opener.focus();
            opener = null;
        }
    }

